def digits(n, s=None):
    s = str(n) if s is None else s
    d0 = int(s[0])
    d1 = int(s[1]) if len(s) > 1 else 1
    d2 = int(s[2]) if len(s) > 2 else 1
    odd_digits = [d for d in (d0, d1, d2) if d % 2 == 1]
    even_digits = [d for d in (d0, d1, d2) if d % 2 == 0]
    prod_odd = 1
    for od in odd_digits:
        prod_odd *= od
    prod_even = 1
    for ed in even_digits:
        prod_even *= ed
    has_odd = len(odd_digits) > 0
    has_even = len(even_digits) > 0
    if has_odd and (not has_even):
        if isinstance(n, str):
            return str(prod_odd)
        else:
            return prod_odd
    if has_even and (not has_odd):
        if isinstance(n, int) and len(s) == 1:
            return 0
        else:
            return '0'
    if has_odd and has_even:
        if isinstance(n, str):
            return str(prod_odd)
        else:
            return prod_odd
    return None
