def dif_Square(n: int) -> bool:
    """
    Check if the integer n can be represented as a difference of two squares
    of non-negative integers, i.e., n = a^2 - b^2 with a, b >= 0.

    Returns True if such a representation exists, False otherwise.
    """
    if n == 0:
        return True
    abs_n = abs(n)
    from math import isqrt
    for x in range(0, isqrt(abs_n) + 1):
        if x == 0:
            if n == 0:
                return True
            continue
        if n % x != 0:
            continue
        y = n // x
        if x > y:
            continue
        if (x + y) % 2 != 0:
            continue
        a = (x + y) // 2
        b = (y - x) // 2
        if b < 0:
            continue
        if a * a - b * b == n:
            return True
    if n >= 0:
        r = isqrt(n)
        if r * r == n:
            return True
    return False

