def next_smallest_palindrome(num: int) -> int:
    """
    Return the smallest palindrome strictly greater than the given number `num`.
    """

    def is_all_nines(n_str):
        return all((ch == '9' for ch in n_str))
    s = str(num)
    length = len(s)
    if is_all_nines(s):
        return int('1' + '0' * (length - 1) + '1')
    digits = list(s)

    def make_palindrome(left, length):
        if length % 2 == 0:
            return left + left[::-1]
        else:
            return left + left[-2::-1]
    half_len = (length + 1) // 2
    left = digits[:half_len]
    palindrome = list(make_palindrome(left, length))
    palindrome_num = int(''.join(palindrome))
    if palindrome_num > num:
        return palindrome_num
    left_int = int(''.join(left)) + 1
    left_str = str(left_int)
    if len(left_str) > len(left):
        return int('1' + '0' * (length - 1) + '1')
    else:
        palindrome = list(make_palindrome(left_str, length))
        return int(''.join(palindrome))

