def next_smallest_palindrome(n: int) -> int:
    """
    Return the smallest palindrome strictly greater than n.
    """
    s = str(n)
    length = len(s)

    def is_all_nines(s):
        return all((ch == '9' for ch in s))
    if is_all_nines(s):
        return int('1' + '0' * (length - 1) + '1')

    def make_palindrome(left, odd_length):
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]
    odd = length % 2 != 0
    mid = length // 2
    if odd:
        left = s[:mid + 1]
    else:
        left = s[:mid]
    candidate = int(make_palindrome(left, odd))
    if candidate > n:
        return candidate
    left_num = int(left)
    left_num += 1
    left_str = str(left_num)
    if len(left_str) > len(left):
        if odd:
            return int(left_str + left_str[:-1][::-1])
        else:
            return int(left_str + left_str[::-1])
    else:
        return int(make_palindrome(left_str, odd))

