def find_solution(a: int, b: int, n: int):
    """
    Find the first non-negative integer solution (x, y) to the equation a*x + b*y = n,
    where x starts from 0 and increases upward.

    Returns:
        A tuple (x, y) if a solution exists with x, y >= 0.
        None if no such solution exists.
    """
    if a == 0 and b == 0:
        if n == 0:
            return (0, 0)
        else:
            return None
    if a == 0:
        if b != 0 and n % b == 0:
            y = n // b
            if y >= 0:
                return (0, y)
        return None
    if b == 0:
        if a != 0 and n % a == 0:
            x = n // a
            if x >= 0:
                return (x, 0)
        return None
    x = 0
    while a * x <= n:
        remainder = n - a * x
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
