def find_solution(a: int, b: int, n: int):
    """
    Find non-negative integers x, y such that a*x + b*y = n.
    Return a tuple (x, y) if such a solution exists, else return None.
    """
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return None
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None

    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        g, s, t = extended_gcd(y, x % y)
        return (g, t, s - x // y * t)
    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return None
    x0 *= n // g
    y0 *= n // g
    a_div = a // g
    b_div = b // g
    import math
    k_min = math.ceil(-x0 / b_div)
    k_max = math.floor(y0 / a_div)
    if k_min > k_max:
        return None
    k = k_min
    x = x0 + k * b_div
    y = y0 - k * a_div
    if x >= 0 and y >= 0:
        return (x, y)
    else:
        return None

