def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)
    if all((ch == '9' for ch in s)):
        return int('1' + '0' * (length - 1) + '1')

    def make_palindrome(left: str, odd_length: bool) -> str:
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]
    odd = length % 2 != 0
    mid = length // 2
    if odd:
        left = s[:mid + 1]
    else:
        left = s[:mid]
    palindrome = make_palindrome(left, odd)
    if int(palindrome) > num:
        return int(palindrome)
    left_num = int(left)
    left_num += 1
    left = str(left_num)
    if len(left) > (mid + 1 if odd else mid):
        return int('1' + '0' * (length - 1) + '1')
    palindrome = make_palindrome(left, odd)
    return int(palindrome)

