    def make_palindrome(left: str, middle: str, is_odd: bool) -> str:
        if is_odd:
            return left + middle + left[::-1]
        else:
            return left + left[::-1]
    is_odd = length % 2 != 0
    half_len = length // 2
    if is_odd:
        left = s[:half_len]
        middle = s[half_len]
        right = s[half_len + 1:]
    else:
        left = s[:half_len]
        middle = ''
        right = s[half_len:]
    pal = make_palindrome(left, middle, is_odd)
    if int(pal) > num:
        return int(pal)
    if is_odd:
        left_middle_num = int(left + middle)
        left_middle_num += 1
        left_middle_str = str(left_middle_num)
        if len(left_middle_str) > len(left + middle):
