    def make_palindrome(left, odd_length):
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]

    def increment_middle(left, odd_length):
        if odd_length:
            left_num = int(left)
            left_num += 1
            left = str(left_num)
            return left
        else:
            left_num = int(left)
            left_num += 1
            left = str(left_num)
